// before — must clause scores every document, defeats caching
{ "query": { "bool": { "must": [
  { "term": { "status": "active" } },
  { "range": { "created_at": { "gte": "now-7d" } } }
] } } }

// after — filter context skips scoring, cacheable
{ "query": { "bool": { "filter": [
  { "term": { "status": "active" } },
  { "range": { "created_at": { "gte": "now-7d" } } }
] } } }
